                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.setdefault(color, []).append(cells)

    if len(components) != 2:
        return [row[:] for row in grid]

    # Place the color whose objects are furthest left in the left lane.
    left_color, right_color = sorted(
        components, key=lambda color: min(c for obj in components[color] for r, c in obj)
    )
    left_width = max(
        max(c for r, c in obj) - min(c for r, c in obj) + 1
        for obj in components[left_color]
    )
    x_start = {left_color: 0, right_color: left_width + 1}
    out = [[0] * w for _ in range(h)]

    # Put the higher input component in the upper output slot, and the lower
    # component in the bottom slot, keeping each component's shape unchanged.
    for color, objects in components.items():
        objects = sorted(objects, key=lambda obj: min(r for r, c in obj))
        for i, obj in enumerate(objects):
            r0 = min(r for r, c in obj)
            c0 = min(c for r, c in obj)
            height = max(r for r, c in obj) - r0 + 1
            top = (6 - height) if i == 0 else (h - height)
            for r, c in obj:
                y = top + r - r0
                x = x_start[color] + c - c0
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color

    return out
